import {
  useCallback,
  useEffect,
  useLayoutEffect,
  useMemo,
  useRef,
  useState,
} from "react";
import { setIcon } from "obsidian";
import { TLShapeId, useEditor, useValue } from "tldraw";
import DiscourseGraphPlugin from "~/index";
import { DiscourseRelationShape } from "~/components/canvas/shapes/DiscourseRelationShape";
import {
  getArrowBindings,
  getArrowInfo,
} from "~/components/canvas/utils/relationUtils";
import { CreateRelationTypeModal } from "~/components/canvas/CreateRelationTypeModal";
import {
  associateRelationTypeWithNodePair,
  createRelationTypeForNodePair,
  getAssociableRelationTypesForNodePair,
  getDiscourseNodeTypeId,
  getValidRelationTypesForNodePair,
} from "~/components/canvas/utils/relationTypeUtils";
import { showToast } from "~/components/canvas/utils/toastUtils";
import { getNodeTypeById } from "~/utils/typeUtils";
import type { DiscourseRelationType } from "~/types";
import { clampMenuCentre } from "~/components/canvas/utils/menuPlacement";

type RelationTypeDropdownProps = {
  arrowId: TLShapeId;
  plugin: DiscourseGraphPlugin;
  canvasPath: string;
  onSelect: (relationTypeId: string) => void;
  onDismiss: () => void;
};

export const RelationTypeDropdown = ({
  arrowId,
  plugin,
  canvasPath,
  onSelect,
  onDismiss,
}: RelationTypeDropdownProps) => {
  const editor = useEditor();
  const dropdownRef = useRef<HTMLDivElement>(null);
  const [isAddMenuOpen, setIsAddMenuOpen] = useState(false);
  const [isPickingExisting, setIsPickingExisting] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  // The dialog sits outside dropdownRef, so its clicks and Escape must not dismiss the menu
  const [isCreateDialogOpen, setIsCreateDialogOpen] = useState(false);

  const arrow = useValue<DiscourseRelationShape | null>(
    "dropdownArrow",
    () => editor.getShape<DiscourseRelationShape>(arrowId) ?? null,
    [editor, arrowId],
  );

  // Auto-dismiss if arrow is deleted
  useEffect(() => {
    if (!arrow) {
      onDismiss();
    }
  }, [arrow, onDismiss]);

  const nodePair = useMemo(() => {
    if (!arrow) return null;

    const bindings = getArrowBindings(editor, arrow);
    if (!bindings.start || !bindings.end) return null;

    const sourceNodeTypeId = getDiscourseNodeTypeId(
      editor.getShape(bindings.start.toId),
    );
    const targetNodeTypeId = getDiscourseNodeTypeId(
      editor.getShape(bindings.end.toId),
    );
    if (!sourceNodeTypeId || !targetNodeTypeId) return null;

    return { sourceNodeTypeId, targetNodeTypeId };
  }, [arrow, editor]);

  // Associating replaces the discourseRelations array, so its identity refreshes both lists
  const { relationTypes, discourseRelations } = plugin.settings;
  const validRelationTypes = useMemo(
    () =>
      nodePair
        ? getValidRelationTypesForNodePair({
            settings: { relationTypes, discourseRelations },
            ...nodePair,
          })
        : [],
    [nodePair, relationTypes, discourseRelations],
  );
  const associableRelationTypes = useMemo(
    () =>
      nodePair
        ? getAssociableRelationTypesForNodePair({
            settings: { relationTypes, discourseRelations },
            ...nodePair,
          })
        : [],
    [nodePair, relationTypes, discourseRelations],
  );

  // Position dropdown at arrow midpoint
  const dropdownPosition = useValue<{ left: number; top: number } | null>(
    "dropdownPosition",
    () => {
      if (!arrow) return null;

      const info = getArrowInfo(editor, arrow);
      if (!info) return null;

      // Get the midpoint in page space
      const pageTransform = editor.getShapePageTransform(arrow.id);
      const midInPage = pageTransform.applyToPoint(info.middle);

      const vp = editor.pageToViewport(midInPage);
      return { left: vp.x, top: vp.y };
    },
    [editor, arrow?.id],
  );

  const viewport = useValue(
    "dropdownViewport",
    () => {
      const bounds = editor.getViewportScreenBounds();
      return { width: bounds.w, height: bounds.h };
    },
    [editor],
  );

  // Measured before paint so the first frame is already inside the canvas.
  const [menuSize, setMenuSize] = useState<{
    menu: { width: number; height: number };
    flyoutWidth: number;
  } | null>(null);
  const hasPosition = !!dropdownPosition;
  const relationTypeCount = validRelationTypes.length;
  const associableCount = associableRelationTypes.length;
  useLayoutEffect(() => {
    const [menu, flyout] = Array.from(
      dropdownRef.current?.children ?? [],
    ) as HTMLElement[];
    if (!menu) return;
    setMenuSize({
      menu: { width: menu.offsetWidth, height: menu.offsetHeight },
      flyoutWidth: flyout
        ? flyout.offsetLeft + flyout.offsetWidth - menu.offsetWidth
        : 0,
    });
  }, [
    hasPosition,
    isAddMenuOpen,
    isPickingExisting,
    relationTypeCount,
    associableCount,
  ]);

  // Handle click outside
  useEffect(() => {
    const handlePointerDown = (e: PointerEvent) => {
      if (isCreateDialogOpen) return;
      if (
        dropdownRef.current &&
        !dropdownRef.current.contains(e.target as Node)
      ) {
        onDismiss();
      }
    };

    // Delay to avoid immediately triggering from the pointer up that opened this
    const timer = setTimeout(() => {
      window.addEventListener("pointerdown", handlePointerDown, true);
    }, 100);

    return () => {
      clearTimeout(timer);
      window.removeEventListener("pointerdown", handlePointerDown, true);
    };
  }, [isCreateDialogOpen, onDismiss]);

  // Handle Escape key: leave the picker or add menu first, then the dropdown
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key !== "Escape" || isCreateDialogOpen) return;
      if (isPickingExisting) {
        e.stopPropagation();
        setIsPickingExisting(false);
        return;
      }
      if (isAddMenuOpen) {
        e.stopPropagation();
        setIsAddMenuOpen(false);
        return;
      }
      onDismiss();
    };
    window.addEventListener("keydown", handleKeyDown, true);
    return () => window.removeEventListener("keydown", handleKeyDown, true);
  }, [isAddMenuOpen, isCreateDialogOpen, isPickingExisting, onDismiss]);

  const handleSelect = useCallback(
    (relationTypeId: string) => {
      onSelect(relationTypeId);
    },
    [onSelect],
  );

  const showRelationAddedToast = useCallback(
    (relationTypeLabel: string) => {
      if (!nodePair) return;
      const sourceName =
        getNodeTypeById(plugin, nodePair.sourceNodeTypeId)?.name ?? "source";
      const targetName =
        getNodeTypeById(plugin, nodePair.targetNodeTypeId)?.name ?? "target";
      showToast({
        severity: "success",
        title: "Discourse relation added",
        description: `${relationTypeLabel} relation added for ${sourceName} and ${targetName}`,
        targetCanvasId: canvasPath,
      });
    },
    [nodePair, plugin, canvasPath],
  );

  const handleAssociate = useCallback(
    async (relationType: DiscourseRelationType) => {
      if (!nodePair || isSaving) return;
      setIsSaving(true);
      try {
        await associateRelationTypeWithNodePair({
          plugin,
          relationTypeId: relationType.id,
          ...nodePair,
        });
      } catch {
        showToast({
          severity: "error",
          title: "Couldn't add relation",
          targetCanvasId: canvasPath,
        });
        return;
      } finally {
        setIsSaving(false);
      }
      setIsPickingExisting(false);
      showRelationAddedToast(relationType.label);
    },
    [nodePair, isSaving, plugin, canvasPath, showRelationAddedToast],
  );

  const handleCreateNew = useCallback(() => {
    if (!nodePair) return;
    setIsAddMenuOpen(false);
    setIsCreateDialogOpen(true);
    new CreateRelationTypeModal(plugin.app, {
      getRelationTypes: () => plugin.settings.relationTypes,
      onSubmit: async (fields) => {
        const relationType = await createRelationTypeForNodePair({
          plugin,
          ...fields,
          ...nodePair,
        });
        showToast({
          severity: "success",
          title: "Relation type created",
          targetCanvasId: canvasPath,
        });
        showRelationAddedToast(relationType.label);
      },
      onClose: () => setIsCreateDialogOpen(false),
    }).open();
  }, [nodePair, plugin, canvasPath, showRelationAddedToast]);

  if (!dropdownPosition || !arrow) return null;

  const centre = menuSize
    ? clampMenuCentre({
        anchor: { x: dropdownPosition.left, y: dropdownPosition.top },
        ...menuSize,
        viewport,
        margin: 8,
      })
    : { x: dropdownPosition.left, y: dropdownPosition.top };

  const actionClassName =
    "flex w-full cursor-pointer items-center justify-start rounded border-none bg-transparent px-2 py-1.5 text-left text-sm font-medium text-gray-700 hover:bg-gray-100";
  const addActions = (
    <>
      <button
        className={actionClassName}
        onClick={() => {
          setIsAddMenuOpen(false);
          setIsPickingExisting(true);
        }}
      >
        Add existing…
      </button>
      <button className={actionClassName} onClick={handleCreateNew}>
        Create new
      </button>
    </>
  );
  const hasRelationTypes = validRelationTypes.length > 0;
  const listContent = hasRelationTypes
    ? validRelationTypes.map((rt) => (
        <button
          key={rt.id}
          onClick={() => handleSelect(rt.id)}
          className="flex w-full cursor-pointer items-center gap-2 rounded border-none bg-transparent px-2 py-1.5 text-left text-sm text-gray-700 hover:bg-gray-100"
        >
          <span
            className="h-2 w-2 shrink-0 rounded-full"
            style={{ backgroundColor: rt.color }}
          />
          {rt.label}
        </button>
      ))
    : addActions;
  const pickerContent =
    associableRelationTypes.length > 0 ? (
      associableRelationTypes.map((rt) => (
        <button
          key={rt.id}
          disabled={isSaving}
          onClick={() => void handleAssociate(rt)}
          className={actionClassName}
        >
          {rt.label} / {rt.complement}
        </button>
      ))
    ) : (
      <p className="m-0 px-2 py-1.5 text-sm text-gray-500">
        All relation types are already available for these nodes
      </p>
    );

  return (
    <div
      ref={dropdownRef}
      // Above tldraw's panels (z 300), below its menus (z 400). Arbitrary transform because preflight is off.
      className="pointer-events-auto absolute z-[301] [transform:translate(-50%,-50%)]"
      style={{
        left: `${centre.x}px`,
        top: `${centre.y}px`,
      }}
      onPointerDown={(e) => e.stopPropagation()}
      onPointerUp={(e) => e.stopPropagation()}
      onClick={(e) => e.stopPropagation()}
    >
      <div className="max-h-60 min-w-40 overflow-y-auto rounded-lg border bg-white p-1 shadow-lg">
        <div className="flex items-center justify-between gap-1 px-2 py-1">
          {isPickingExisting && (
            <button
              aria-label="Back to relation types"
              onClick={() => setIsPickingExisting(false)}
              className="flex h-auto cursor-pointer items-center rounded border-none bg-transparent p-0.5 text-gray-500 hover:bg-gray-100"
              ref={(el) => (el && setIcon(el, "chevron-left")) || undefined}
            />
          )}
          <span className="mr-auto text-xs font-medium uppercase tracking-wide text-gray-500">
            Relation type
          </span>
          {hasRelationTypes && !isPickingExisting && (
            <button
              aria-label="Add relation type"
              aria-expanded={isAddMenuOpen}
              onClick={() => setIsAddMenuOpen((open) => !open)}
              className="flex h-auto cursor-pointer items-center rounded border-none bg-transparent p-0.5 text-gray-500 hover:bg-gray-100"
              ref={(el) => (el && setIcon(el, "plus")) || undefined}
            />
          )}
        </div>
        {isPickingExisting ? pickerContent : listContent}
      </div>
      {/* Outside the scroll container so it isn't clipped, inside dropdownRef so clicks don't dismiss */}
      {hasRelationTypes && isAddMenuOpen && (
        <div className="absolute left-full top-0 ml-1 min-w-32 rounded-lg border bg-white p-1 shadow-lg">
          {addActions}
        </div>
      )}
    </div>
  );
};

import { App, Modal } from "obsidian";
import { StrictMode, useState } from "react";
import { createRoot, Root } from "react-dom/client";
import { ColorPicker } from "~/components/RelationshipTypeSettings";
import type { DiscourseRelationType } from "~/types";
import {
  DEFAULT_TLDRAW_COLOR,
  type TldrawColorName,
} from "~/utils/tldrawColors";
import { getRelationTypeErrors } from "~/utils/typeUtils";

type RelationTypeFields = {
  label: string;
  complement: string;
  color: TldrawColorName;
};

type CreateRelationTypeProps = {
  // Read at submit: another canvas may add a type while the dialog is open
  getRelationTypes: () => DiscourseRelationType[];
  onSubmit: (fields: RelationTypeFields) => Promise<void>;
  onClose: () => void;
};

const CreateRelationTypeForm = ({
  getRelationTypes,
  onSubmit,
  onClose,
}: CreateRelationTypeProps) => {
  const [label, setLabel] = useState("");
  const [complement, setComplement] = useState("");
  const [color, setColor] = useState<TldrawColorName>(DEFAULT_TLDRAW_COLOR);
  const [error, setError] = useState("");
  const [isSubmitting, setIsSubmitting] = useState(false);

  const handleSubmit = async () => {
    // Trimmed so "supports " can't pass as a second "supports"
    const fields = {
      label: label.trim(),
      complement: complement.trim(),
      color,
    };
    const candidate = { id: "new", ...fields, created: 0, modified: 0 };
    const relationTypes = getRelationTypes();
    const nextError = !fields.label
      ? "Label is required"
      : !fields.complement
        ? "Complement is required"
        : (getRelationTypeErrors([...relationTypes, candidate])[
            relationTypes.length
          ] ?? "");
    setError(nextError);
    if (nextError) return;

    setIsSubmitting(true);
    try {
      await onSubmit(fields);
    } catch {
      setError("Couldn't save the relation type. Try again.");
      setIsSubmitting(false);
      return;
    }
    onClose();
  };

  const inputClassName = `w-full ${error ? "input-error" : ""}`;

  return (
    <form
      className="flex flex-col gap-3"
      onSubmit={(e) => {
        e.preventDefault();
        void handleSubmit();
      }}
    >
      <input
        type="text"
        className={inputClassName}
        placeholder="Label (e.g., supports)"
        value={label}
        onChange={(e) => setLabel(e.target.value)}
        autoFocus
      />
      <input
        type="text"
        className={inputClassName}
        placeholder="Complement (e.g., is supported by)"
        value={complement}
        onChange={(e) => setComplement(e.target.value)}
      />
      <ColorPicker value={color} onChange={setColor} />
      {error && <div className="text-error text-xs">{error}</div>}
      <div className="modal-button-container mt-2 flex justify-end gap-2">
        <button
          type="button"
          className="mod-normal"
          onClick={onClose}
          disabled={isSubmitting}
        >
          Cancel
        </button>
        <button type="submit" className="mod-cta" disabled={isSubmitting}>
          Continue
        </button>
      </div>
    </form>
  );
};

export class CreateRelationTypeModal extends Modal {
  private root: Root | null = null;
  private props: CreateRelationTypeProps;
  private isSaving = false;

  constructor(app: App, props: CreateRelationTypeProps) {
    super(app);
    this.props = props;
  }

  // Escape and the backdrop call close(); a pending save must finish first
  close() {
    if (!this.isSaving) super.close();
  }

  onOpen() {
    this.setTitle("Add relation type");
    // The color list is absolutely positioned and extends past this short form
    this.modalEl.addClass("overflow-visible");
    this.root = createRoot(this.contentEl);
    this.root.render(
      <StrictMode>
        <CreateRelationTypeForm
          getRelationTypes={this.props.getRelationTypes}
          onSubmit={async (fields) => {
            this.isSaving = true;
            try {
              await this.props.onSubmit(fields);
            } finally {
              this.isSaving = false;
            }
          }}
          onClose={() => this.close()}
        />
      </StrictMode>,
    );
  }

  onClose() {
    this.root?.unmount();
    this.root = null;
    this.contentEl.empty();
    this.props.onClose();
  }
}
import type { Editor, TLShape, TLShapeId, VecLike } from "tldraw";
import type { DiscourseNodeShape } from "~/components/canvas/shapes/DiscourseNodeShape";
import type DiscourseGraphPlugin from "~/index";
import type { DiscourseRelation, DiscourseRelationType } from "~/types";
import generateUid from "~/utils/generateUid";
import { COLOR_PALETTE, type TldrawColorName } from "~/utils/tldrawColors";
import { isAcceptedSchema } from "~/utils/typeUtils";

export const isDiscourseNodeShape = (
  shape: TLShape | null | undefined,
): shape is DiscourseNodeShape => shape?.type === "discourse-node";

/**
 * Finds the discourse node shape at a given page point, excluding an optional
 * shape by ID (e.g. the source node or the relation arrow itself).
 */
export const getDiscourseNodeAtPoint = (
  editor: Editor,
  point: VecLike,
  excludeShapeId?: TLShapeId,
): TLShape | undefined => {
  return editor.getShapeAtPoint(point, {
    hitInside: true,
    hitFrameInside: true,
    margin: 0,
    filter: (targetShape) =>
      targetShape.type === "discourse-node" &&
      !targetShape.isLocked &&
      targetShape.id !== excludeShapeId,
  });
};

/**
 * Extracts the nodeTypeId from any tldraw shape that may have it.
 * Avoids repeating the same unsafe cast across multiple files.
 */
export const getDiscourseNodeTypeId = (shape: unknown): string | undefined => {
  const typed = shape as { props?: { nodeTypeId?: string } } | null | undefined;
  return typed?.props?.nodeTypeId;
};

type RelationTypeSettings = {
  discourseRelations: DiscourseRelation[];
  relationTypes: DiscourseRelationType[];
};

/**
 * Checks the direction of a discourse relation between two node types.
 * Returns whether the relation exists in the direct (source→target)
 * and/or reverse (target→source) direction.
 */
export const getRelationDirection = ({
  discourseRelations,
  relationTypeId,
  sourceNodeTypeId,
  targetNodeTypeId,
}: {
  discourseRelations: DiscourseRelation[];
  relationTypeId: string;
  sourceNodeTypeId: string;
  targetNodeTypeId: string;
}): { direct: boolean; reverse: boolean } => {
  let direct = false;
  let reverse = false;

  for (const relation of discourseRelations) {
    if (relation.relationshipTypeId !== relationTypeId) continue;
    if (
      relation.sourceId === sourceNodeTypeId &&
      relation.destinationId === targetNodeTypeId
    ) {
      direct = true;
    }
    if (
      relation.sourceId === targetNodeTypeId &&
      relation.destinationId === sourceNodeTypeId
    ) {
      reverse = true;
    }
    if (direct && reverse) break;
  }

  return { direct, reverse };
};

export const getRelationLabelForDirection = ({
  discourseRelations,
  relationType,
  sourceNodeTypeId,
  targetNodeTypeId,
}: {
  discourseRelations: DiscourseRelation[];
  relationType: DiscourseRelationType;
  sourceNodeTypeId: string;
  targetNodeTypeId: string;
}): string => {
  const { direct, reverse } = getRelationDirection({
    discourseRelations,
    relationTypeId: relationType.id,
    sourceNodeTypeId,
    targetNodeTypeId,
  });

  if (reverse && !direct) {
    return relationType.complement;
  }

  return relationType.label;
};

/**
 * Returns the list of valid relation types for a given pair of node types,
 * checking both directions of the discourse relations.
 */
export const getValidRelationTypesForNodePair = ({
  settings,
  sourceNodeTypeId,
  targetNodeTypeId,
}: {
  settings: RelationTypeSettings;
  sourceNodeTypeId: string;
  targetNodeTypeId: string;
}): { id: string; label: string; color: string }[] => {
  const validTypes: { id: string; label: string; color: string }[] = [];

  for (const relationType of settings.relationTypes) {
    const { direct, reverse } = getRelationDirection({
      discourseRelations: settings.discourseRelations,
      relationTypeId: relationType.id,
      sourceNodeTypeId,
      targetNodeTypeId,
    });

    if (direct || reverse) {
      validTypes.push({
        id: relationType.id,
        label: relationType.label,
        color: COLOR_PALETTE[relationType.color] ?? COLOR_PALETTE["black"]!,
      });
    }
  }

  return validTypes;
};

/**
 * Returns the accepted relation types not yet valid for a node pair in either
 * direction, which the "Add existing" picker offers.
 */
export const getAssociableRelationTypesForNodePair = ({
  settings,
  sourceNodeTypeId,
  targetNodeTypeId,
}: {
  settings: RelationTypeSettings;
  sourceNodeTypeId: string;
  targetNodeTypeId: string;
}): DiscourseRelationType[] =>
  settings.relationTypes.filter((relationType) => {
    if (!isAcceptedSchema(relationType)) return false;
    const { direct, reverse } = getRelationDirection({
      discourseRelations: settings.discourseRelations,
      relationTypeId: relationType.id,
      sourceNodeTypeId,
      targetNodeTypeId,
    });
    return !direct && !reverse;
  });

/**
 * Makes a relation type valid for a source → target node pair and saves it.
 * Removes the added relation again if the save fails.
 */
export const associateRelationTypeWithNodePair = async ({
  plugin,
  relationTypeId,
  sourceNodeTypeId,
  targetNodeTypeId,
}: {
  plugin: DiscourseGraphPlugin;
  relationTypeId: string;
  sourceNodeTypeId: string;
  targetNodeTypeId: string;
}): Promise<void> => {
  const now = Date.now();
  const relation: DiscourseRelation = {
    id: generateUid("rel3"),
    sourceId: sourceNodeTypeId,
    destinationId: targetNodeTypeId,
    relationshipTypeId: relationTypeId,
    created: now,
    modified: now,
  };
  plugin.settings.discourseRelations = [
    ...plugin.settings.discourseRelations,
    relation,
  ];
  try {
    await plugin.saveSettings();
  } catch (error) {
    // Filter by id: another association may have saved while this one was pending
    plugin.settings.discourseRelations =
      plugin.settings.discourseRelations.filter(({ id }) => id !== relation.id);
    throw error;
  }
};

/**
 * Creates a relation type, makes it valid for a source → target node pair and
 * saves once. Removes the added type and relation again if the save fails.
 */
export const createRelationTypeForNodePair = async ({
  plugin,
  label,
  complement,
  color,
  sourceNodeTypeId,
  targetNodeTypeId,
}: {
  plugin: DiscourseGraphPlugin;
  label: string;
  complement: string;
  color: TldrawColorName;
  sourceNodeTypeId: string;
  targetNodeTypeId: string;
}): Promise<DiscourseRelationType> => {
  const now = Date.now();
  const relationType: DiscourseRelationType = {
    id: generateUid("rel"),
    label,
    complement,
    color,
    created: now,
    modified: now,
  };
  plugin.settings.relationTypes = [
    ...plugin.settings.relationTypes,
    relationType,
  ];
  try {
    await associateRelationTypeWithNodePair({
      plugin,
      relationTypeId: relationType.id,
      sourceNodeTypeId,
      targetNodeTypeId,
    });
  } catch (error) {
    // Filter by id, as the association helper does, so concurrent saves survive
    plugin.settings.relationTypes = plugin.settings.relationTypes.filter(
      ({ id }) => id !== relationType.id,
    );
    throw error;
  }
  return relationType;
};

/**
 * Checks whether a specific relation type can connect the given source and
 * target node types (in either direction).
 */
export const isValidRelationConnection = ({
  discourseRelations,
  relationTypeId,
  sourceNodeTypeId,
  targetNodeTypeId,
}: {
  discourseRelations: DiscourseRelation[];
  relationTypeId: string;
  sourceNodeTypeId: string;
  targetNodeTypeId: string;
}): boolean => {
  const { direct, reverse } = getRelationDirection({
    discourseRelations,
    relationTypeId,
    sourceNodeTypeId,
    targetNodeTypeId,
  });
  return direct || reverse;
};

/**
 * Returns the valid target node type IDs for a given relation type and source
 * node type, checking both forward and reverse directions.
 */
export const getCompatibleTargetNodeTypeIds = ({
  discourseRelations,
  relationTypeId,
  sourceNodeTypeId,
}: {
  discourseRelations: DiscourseRelation[];
  relationTypeId: string;
  sourceNodeTypeId: string;
}): string[] => {
  const targets = new Set<string>();
  for (const relation of discourseRelations) {
    if (relation.relationshipTypeId !== relationTypeId) continue;
    if (relation.sourceId === sourceNodeTypeId)
      targets.add(relation.destinationId);
    if (relation.destinationId === sourceNodeTypeId)
      targets.add(relation.sourceId);
  }
  return [...targets];
};

